section.programlisting:
; Die Matrix: eine Zahl für jede Zeile i und Spalte j.
function a(i: i32, j: i32) returns f64
    1.0 / ((((i + j) * (i + j + 1)) / 2 + i + 1) as f64)

; Die Matrix mal einen Vektor, oder die gedrehte Matrix: eine Summe
; über die Spalten für jede Zeile -- in f64 und in f32.
procedure times(v: Vector[f64], mutable out: Vector[f64], turned: bool)
{
    let n v.length as i32
    for i in n
    {
        var sum 0.0
        for j in n
            sum := sum + (if turned: a(j, i) else a(i, j)) * v[j as size_t]
        out.put(i as size_t, sum)
    }
}

procedure times32(v: Vector[f32], mutable out: Vector[f32], turned: bool)
{
    let n v.length as i32
    relaxed for i in n
    {
        var sum: f32 0.0
        for j in n
            sum := sum + (if turned: a(j, i) as f32 else a(i, j) as f32) * v[j as size_t]
        out.put(i as size_t, sum)
    }
}

; wie viele Stellen einer Schätzung stimmen
function digits(guess: f64, truth: f64) returns f64
{
    let off ((guess - truth) / truth).abs()
    if off < 0.0000000000000001
        return 16.0
    0.0 - log10(off)
}

let n: size_t 300
let rounds 10
var u Vector[f64](n)
var v Vector[f64](n)
var t Vector[f64](n)
var u32 Vector[f32](n)
var v32 Vector[f32](n)
var t32 Vector[f32](n)
for k in n
{
    u.put(k, 1.0)
    u32.put(k, 1.0)
}
var guess64 Array[f64]()
var guess32 Array[f64]()
for r in rounds
{
    times(u, t, false)
    times(t, v, true)
    times(v, t, false)
    times(t, u, true)
    times32(u32, t32, false)
    times32(t32, v32, true)
    times32(v32, t32, false)
    times32(t32, u32, true)
    var uv 0.0
    var vv 0.0
    var uv32: f32 0.0
    var vv32: f32 0.0
    for k in n
    {
        uv := uv + u[k] * v[k]
        vv := vv + v[k] * v[k]
        uv32 := uv32 + u32[k] * v32[k]
        vv32 := vv32 + v32[k] * v32[k]
    }
    guess64.add((uv / vv).sqrt())
    guess32.add(((uv32 / vv32) as f64).sqrt())
}
let truth guess64[guess64.length - 1]
print "der größte Singulärwert: `truth`"
var chart Chart("Richtige Stellen, Runde für Runde")
chart.axes("Runde", "Stellen")
chart.series("f64")
for r in rounds
    chart.point(r + 1, digits(guess64[r as size_t], truth))
chart.series("f32")
for r in rounds
    chart.point(r + 1, digits(guess32[r as size_t], truth))
chart.show()
